package com.github.games647.changeskin.sponge.bungee;

import com.github.games647.changeskin.core.message.NamespaceKey;
import com.github.games647.changeskin.core.message.SkinUpdateMessage;
import com.github.games647.changeskin.sponge.ChangeSkinSponge;
import com.github.games647.changeskin.sponge.task.SkinApplier;
import com.google.common.io.ByteArrayDataInput;
import com.google.common.io.ByteStreams;
import com.google.inject.Inject;

import java.util.Optional;

import io.netty.buffer.ByteBuf;
import org.spongepowered.api.Sponge;
import org.spongepowered.api.entity.living.player.Player;
import org.spongepowered.api.network.ChannelBinding;
import org.spongepowered.api.network.channel.PluginChannelListener;
import org.spongepowered.api.network.channel.payload.PayloadChannel;
import org.spongepowered.api.network.channel.payload.PayloadSide;

import static com.github.games647.changeskin.core.message.SkinUpdateMessage.UPDATE_SKIN_CHANNEL;
import static com.github.games647.changeskin.sponge.PomData.ARTIFACT_ID;

public class UpdateSkinListener implements PluginChannelListener {

    private final ChangeSkinSponge plugin;
    private final PayloadChannel updateSkinChannel;

    @Inject
    UpdateSkinListener(ChangeSkinSponge plugin, ChannelBinding.Factory channelBinding) {
        this.plugin = plugin;

        String combinedName = new NamespaceKey(ARTIFACT_ID, UPDATE_SKIN_CHANNEL).getCombinedName();
        updateSkinChannel = channelBinding.getOrCreatePayload(plugin, combinedName);
    }

    @Override
    public void handlePayload(PayloadSide side, Player player, ByteBuf data) {
        ByteArrayDataInput dataInput = ByteStreams.newDataInput(data.array());
        SkinUpdateMessage updateMessage = new SkinUpdateMessage();
        updateMessage.readFrom(dataInput);

        String playerName = updateMessage.getPlayerName();
        Optional<Player> receiver = Sponge.getServer().getPlayer(playerName);
        if (receiver.isPresent()) {
            Runnable skinUpdater = new SkinApplier(plugin, player, receiver.get(), null, false);
            plugin.getCore().getLogger().info("Skin update for " + playerName);
        }
    }
}

